14: function createStaffSession(prefix: string): StaffSession {
15:   const tokenKey = `jaadoo_${prefix}_token`;
16:   const refreshKey = `jaadoo_${prefix}_refresh_token`;
17:   const expiredEvent = `jaadoo-${prefix}-session-expired`;
18:   const refreshedEvent = `jaadoo-${prefix}-token-refreshed`;
19:   let refreshInFlight: Promise<string | null> | null = null;
20: 
21:   const refresh = (): Promise<string | null> => {
22:     // Share one refresh between requests that hit 401 at the same time
23:     if (!refreshInFlight) {
24:       refreshInFlight = (async () => {
25:         const refreshToken = localStorage.getItem(refreshKey);
26:         if (!refreshToken) return null;
27:         try {
28:           const res = await fetch("/api/v1/auth/refresh", {
29:             method: "POST",
30:             headers: { "Content-Type": "application/json" },
31:             body: JSON.stringify({ refresh_token: refreshToken }),
32:           });
33:           if (!res.ok) return null;
34:           const data = await res.json();
35:           localStorage.setItem(tokenKey, data.access_token);
36:           if (data.refresh_token) localStorage.setItem(refreshKey, data.refresh_token);
37:           window.dispatchEvent(new CustomEvent(refreshedEvent, { detail: data.access_token }));
38:           return data.access_token as string;
39:         } catch {
40:           return null;
41:         } finally {
42:           refreshInFlight = null;
43:         }
44:       })();
45:     }
46:     return refreshInFlight;
47:   };
48: 
49:   const sessionFetch = async (input: string, init: RequestInit = {}): Promise<Response> => {
50:     if (!new Headers(init.headers).has("Authorization")) return fetch(input, init);
51: 
52:     const withToken = (token: string): RequestInit => {
53:       const h = new Headers(init.headers);
54:       h.set("Authorization", `Bearer ${token}`);
55:       return { ...init, headers: h };
56:     };
